css:
/* VIA 對內工作平台 · Dashboard 版面(只有寬度與格線;顏色、字級、燈全部來自 VIA_UI_WorkPlatform_TemplateLock)*/
.wrap.dash{max-width:none;margin:0;padding:10px 14px 30px}
.sysrow{grid-template-columns:repeat(auto-fit,minmax(170px,1fr))}
.grid3{display:grid;grid-template-columns:2fr 1.2fr 1.2fr;gap:10px;align-items:start;margin:0 0 10px}
.grid3>.card{margin:0}
.grid3 .cards{grid-template-columns:repeat(auto-fill,minmax(150px,1fr));margin:0}
.grid3 pre{max-height:260px;overflow:auto}
.mb{display:flex;height:5px;margin-top:4px;border-radius:3px;overflow:hidden}
.mb i{display:block;height:5px;padding:0;border-radius:0;min-width:0;font-size:0;animation:none}
.chip{display:inline-block;border:1px solid var(--line);border-radius:10px;padding:0 6px;font-size:10px;font-weight:400;margin-left:6px}
@media (max-width:1100px){.grid3{grid-template-columns:1fr}}
